<?php
namespace App\Http\Controllers;use App\Models\{MusicComposition,SheetMusic};use Illuminate\Http\Request;
class MusicLibraryController extends Controller{public function __invoke(Request $r){$q=trim((string)$r->q);$instrument=$r->instrument;$compositions=MusicComposition::where('is_published',true)->when($q,fn($x)=>$x->where(fn($s)=>$s->where('title','like',"%$q%")->orWhere('composer','like',"%$q%")->orWhere('performer','like',"%$q%")))->when($instrument,fn($x)=>$x->where('instrument',$instrument))->orderBy('sort')->orderBy('title')->get();$sheets=SheetMusic::where('is_published',true)->when($q,fn($x)=>$x->where(fn($s)=>$s->where('title','like',"%$q%")->orWhere('composer','like',"%$q%")))->when($instrument,fn($x)=>$x->where('instrument',$instrument))->orderBy('sort')->orderBy('title')->get();$instruments=MusicComposition::whereNotNull('instrument')->pluck('instrument')->merge(SheetMusic::whereNotNull('instrument')->pluck('instrument'))->unique()->sort()->values();return view('music-library.index',compact('compositions','sheets','instruments','q','instrument'));}}